"""Postexit actual link quantities; no new predictor, control, fit or gate rescue."""
from pathlib import Path
import json,hashlib,datetime
import numpy as np
from scipy.spatial.transform import Rotation
from shell_link_measurement import bottom_velocity
H=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def stats(x):
 x=np.asarray(x,float);assert len(x)>0 and np.isfinite(x).all();return dict(samples=len(x),rms=float(np.sqrt(np.mean(x*x))),p50=float(np.percentile(x,50)),p90=float(np.percentile(x,90)),peak=float(x.max()))
def main():
 start=datetime.datetime.now(datetime.timezone.utc).isoformat();p=json.loads((H/'shell_link_protocol.json').read_text());status=json.loads((H/'shell_link_status.json').read_text());assert status['status']=='finished' and status['exit_code']==0;out=H/'shell_link_run';manifest=json.loads((out/'artifact_manifest_post_close.json').read_text());checks=0
 for obj,key in [(p,'source_sha256'),(p,'baseline_artifacts'),(manifest,'artifact_sha256')]:
  for file,s in obj[key].items():assert sha(file)==s,file;checks+=1
 rows=json.loads((out/'actual_link_states.json').read_text());identity=json.loads((out/'actual_link_identity.json').read_text());names=identity['link_names'];b=names.index('base_link');s=names.index('link1');z=np.load(out/'physics.npz');old=np.load(H/'rolling_online_run/physics.npz');t=z['simulation_time_s'];poses=np.asarray([r['poses_xyzw'] for r in rows]);vel=np.asarray([r['velocities_linear_angular_xyz'] for r in rows]);assert poses.shape==(len(t),len(names),7) and vel.shape==(len(t),len(names),6);assert np.array_equal([r['time_s'] for r in rows],t) and all(r['link_names']==names for r in rows);assert np.isfinite(poses).all() and np.isfinite(vel).all() and np.all(np.diff(t)>0)
 equality={k:bool(old[k].shape==z[k].shape and np.array_equal(old[k],z[k],equal_nan=True)) for k in old.files if not k.startswith('raw_simulation_time') and k!='raw_physics_step_index'};assert len(equality)==17 and all(equality.values()),equality
 R=Rotation.from_quat(poses[:,b,3:]).as_matrix();S=Rotation.from_quat(poses[:,s,3:]).as_matrix();rootR=Rotation.from_quat(z['root_quaternion_world_wxyz'][:,[1,2,3,0]]).as_matrix();delta=Rotation.from_matrix(np.transpose(R,(0,2,1))@rootR).magnitude();base_errors=dict(position_peak_m=float(np.max(np.linalg.norm(poses[:,b,:3]-z['root_position_world_m'],axis=1))),orientation_peak_rad=float(delta.max()),angular_peak_rad_s=float(np.max(np.linalg.norm(vel[:,b,3:]-z['angular_velocity_world_rad_s'],axis=1))),linear_peak_m_s=float(np.max(np.linalg.norm(vel[:,b,:3]-z['linear_velocity_world_m_s'],axis=1))))
 com=np.asarray(identity['com_local_xyzw'])[0];shelloffset=com[s,:3];shellcenter=poses[:,s,:3];radius=.4000000059604645
 # SDK velocity point convention is labelled; shell COM offset recorded and ambiguity quantified.
 origin_v_if_com=vel[:,s,:3]+np.cross(vel[:,s,3:],-(S@shelloffset));origin_v_if_origin=vel[:,s,:3];vcompositions=shellcenter+S@shelloffset
 omega_from_base_encoder=vel[:,b,3:]+R[:,:,1]*z['joint_velocity_rad_s'][:,0,None];chain=vel[:,s,3:]-omega_from_base_encoder
 tangent=np.asarray([bottom_velocity(v,w,radius)[:2] for v,w in zip(origin_v_if_com,vel[:,s,3:])]);tangent_alt=np.asarray([bottom_velocity(v,w,radius)[:2] for v,w in zip(origin_v_if_origin,vel[:,s,3:])]);valid=(t>=1)&(abs(shellcenter[:,2]-radius)<=.01);assert valid.any()
 dt=np.diff(t);average_linear=(vel[1:,s,:3]+vel[:-1,s,:3])*.5;origin_step=(shellcenter[1:]-shellcenter[:-1])/dt[:,None];com_step=(vcompositions[1:]-vcompositions[:-1])/dt[:,None];shellpoint_convention=dict(local_com_offset_m=shelloffset.tolist(),local_com_norm_m=float(np.linalg.norm(shelloffset)),mean_velocity_vs_origin_derivative=stats(np.linalg.norm(average_linear-origin_step,axis=1)),mean_velocity_vs_com_derivative=stats(np.linalg.norm(average_linear-com_step,axis=1)),explanation='finite-difference comparisons are measurement diagnostics, not proof of SDK velocity convention or solver-corrected exact rate')
 actual_step_gyro=Rotation.from_matrix(np.transpose(R[:-1],(0,2,1))@R[1:]).as_rotvec()/dt[:,None];gyro_begin=(np.transpose(R[:-1],(0,2,1))@vel[:-1,b,3:,None])[...,0];gyro_end_beginframe=(np.transpose(R[:-1],(0,2,1))@vel[1:,b,3:,None])[...,0];res=actual_step_gyro-gyro_begin
 validstep=valid[:-1]&valid[1:];summary=dict(base_root_comparison=base_errors,shell_encoder_angular_chain=stats(np.linalg.norm(chain[valid],axis=1)),shell_conditional_bottom_tangent_COM_convention=stats(np.linalg.norm(tangent[valid],axis=1)),shell_conditional_bottom_tangent_origin_convention=stats(np.linalg.norm(tangent_alt[valid],axis=1)),base_pose_increment_vs_begin_gyro=stats(np.linalg.norm(res[validstep],axis=1)),base_pose_increment_vs_endpoint_gyro_in_begin_frame=stats(np.linalg.norm((actual_step_gyro-gyro_end_beginframe)[validstep],axis=1)),shell_point_convention=shellpoint_convention,conditional_height_samples=int(valid.sum()),all_samples=len(t),floor_normal=[0,0,1],height_tolerance_m=.01,physical_ground_force_readout=False,contact_slip_certified=False)
 np.savez_compressed(H/'shell_link_measured_residuals.npz',time_s=t,conditional_height_mask=valid,shell_center=shellcenter,shell_omega_world=vel[:,s,3:],shell_omega_from_base_encoder=omega_from_base_encoder,shell_tangent_COM=tangent,shell_tangent_origin=tangent_alt,pose_gyro_residual=res)
 import matplotlib
 matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,axs=plt.subplots(3,1,figsize=(10,8),sharex=True);axs[0].plot(t,np.linalg.norm(chain,axis=1));axs[0].set_ylabel('Shell omega-chain residual(rad/s)');axs[1].plot(t,np.linalg.norm(tangent,axis=1),label='hypothetical bottom tangent');axs[1].plot(t,np.linalg.norm(vel[:,s,:2],axis=1),label='shell measured XY speed');axs[1].legend();axs[1].set_ylabel('m/s');axs[2].plot(t[1:],np.linalg.norm(res,axis=1));axs[2].set_ylabel('Pose increment / gyro residual(rad/s)');axs[2].set_xlabel('Actual simulation time(s)');fig.tight_layout();fig.savefig(H/'shell_link_measurement.png');plt.close(fig)
 metrics=json.loads((out/'metrics.json').read_text());result=dict(started_utc=start,ended_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),actual_status=status,identity=identity,integrity_checks=checks,baseline_exact_nonraw=equality,baseline_exact_nonraw_all=all(equality.values()),summary=summary,original_b0_metrics=metrics,new_nav_success_rate=False,new_estimator_gate=False,old_rejections_preserved=True,whole_research_complete=False);(H/'shell_link_audit.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n');print(json.dumps(summary,indent=2),flush=True)
if __name__=='__main__':main()
